import{_ as l,a0 as d,w as t,s as c,ao as o,I as p,x as n,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"使用 sed 命令查找和替換文件中的字符串的 16 個示例 | LCTT x X-CMD","titleTemplate":false,"description":"使用 sed 命令查找和替換文件中的字符串的 16 個示例 | LCTT (201909) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 sed 命令查找和替換文件中的字符串的 16 個示例 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 sed 命令查找和替換文件中的字符串的 16 個示例 | LCTT (201909) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201909/20190913 How to Find and Replace a String in File Using the sed Command in Linux","title":"使用 sed 命令查找和替換文件中的字符串的 16 個示例","tag":"201909","desc":""},"relativePath":"201909/20190913 How to Find and Replace a String in File Using the sed Command in Linux.md","filePath":"[post].md"}'),u={name:"201909/20190913 How to Find and Replace a String in File Using the sed Command in Linux.md"};function h(r,s,x,g,b,k){const a=d("Link");return t(),c("div",null,[s[15]||(s[15]=o(`<h1 id="使用-sed-命令查找和替換文件中的字符串的-16-個示例" tabindex="-1">使用 sed 命令查找和替換文件中的字符串的 16 個示例 <a class="header-anchor" href="#使用-sed-命令查找和替換文件中的字符串的-16-個示例" aria-label="Permalink to “使用 sed 命令查找和替換文件中的字符串的 16 個示例”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201909/20/210723xf884pafyzf9zf4a.jpg" alt=""></p><p>當你在使用文本文件時，很可能需要查找和替換文件中的字符串。<code>sed</code> 命令主要用於替換一個文件中的文本。在 Linux 中這可以通過使用 <code>sed</code> 命令和 <code>awk</code> 命令來完成。</p><p>在本教程中，我們將告訴你使用 <code>sed</code> 命令如何做到這一點，然後討論討論 <code>awk</code> 命令相關的。</p><h3 id="sed-命令是什麼" tabindex="-1">sed 命令是什麼 <a class="header-anchor" href="#sed-命令是什麼" aria-label="Permalink to “sed 命令是什麼”">​</a></h3><p><code>sed</code> 命令表示 Stream Editor（流編輯器），用來在 Linux 上執行基本的文本操作。它可以執行各種功能，如搜索、查找、修改、插入或刪除文件。</p><p>此外，它也可以執行復雜的正則表達式匹配。</p><p>它可用於以下目的：</p><ul><li>查找和替換匹配給定的格式的內容。</li><li>在指定行查找和替換匹配給定的格式的內容。</li><li>在所有行查找和替換匹配給定的格式的內容。</li><li>搜索並同時替換兩種不同的模式。</li></ul><p>本文列出的十五個例子可以幫助你掌握 <code>sed</code> 命令。</p><p>如果要使用 <code>sed</code> 命令刪除文件中的行，去下面的文章。</p><p>注意：由於這是一篇演示文章，我們使用不帶 <code>-i</code> 選項的 <code>sed</code> 命令，該選項會在 Linux 終端中刪除行並打印文件內容。</p><p>但是，在實際環境中如果你想刪除源文件中的行，使用帶 <code>-i</code> 選項的 <code>sed</code> 命令。</p><p>常見的 <code>sed</code> 替換字符串的語法。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed -i &#39;s/Search_String/Replacement_String/g&#39; Input_File</span></span></code></pre></div><p>首先我們需要了解 <code>sed</code> 語法來做到這一點。請參閲有關的細節。</p><ul><li><code>sed</code>：這是一個 Linux 命令。</li><li><code>-i</code>：這是 <code>sed</code> 命令的一個選項，它有什麼作用？默認情況下，<code>sed</code> 打印結果到標準輸出。當你使用 <code>sed</code> 添加這個選項時，那麼它會在適當的位置修改文件。當你添加一個後綴（比如，<code>-i.bak</code>）時，就會創建原始文件的備份。</li><li><code>s</code>：字母 <code>s</code> 是一個替換命令。</li><li><code>Search_String</code>：搜索一個給定的字符串或正則表達式。</li><li><code>Replacement_String</code>：替換的字符串。</li><li><code>g</code>：全局替換標誌。默認情況下，<code>sed</code> 命令替換每一行第一次出現的模式，它不會替換行中的其他的匹配結果。但是，提供了該替換標誌時，所有匹配都將被替換。</li><li><code>/</code>：分界符。</li><li><code>Input_File</code>：要執行操作的文件名。</li></ul><p>讓我們來看看文件中用sed命令來搜索和轉換文本的一些常用例子。</p><p>我們已經創建了用於演示的以下文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cat sed-test.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1 Unix unix unix 23</span></span>
<span class="line"><span>2 linux Linux 34</span></span>
<span class="line"><span>3 linuxunix UnixLinux</span></span>
<span class="line"><span>linux /bin/bash CentOS Linux OS</span></span>
<span class="line"><span>Linux is free and opensource operating system</span></span></code></pre></div><h3 id="_1-如何查找和替換一行中-第一次-模式匹配" tabindex="-1">1) 如何查找和替換一行中“第一次”模式匹配 <a class="header-anchor" href="#_1-如何查找和替換一行中-第一次-模式匹配" aria-label="Permalink to “1) 如何查找和替換一行中“第一次”模式匹配”">​</a></h3><p>下面的 <code>sed</code> 命令用 <code>linux</code> 替換文件中的 <code>unix</code>。這僅僅改變了每一行模式的第一個實例。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sed &#39;s/unix/linux/&#39; sed-test.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1 Unix linux unix 23</span></span>
<span class="line"><span>2 linux Linux 34</span></span>
<span class="line"><span>3 linuxlinux UnixLinux</span></span>
<span class="line"><span>linux /bin/bash CentOS Linux OS</span></span>
<span class="line"><span>Linux is free and opensource operating system</span></span></code></pre></div><h3 id="_2-如何查找和替換每一行中-第-n-次-出現的模式" tabindex="-1">2) 如何查找和替換每一行中“第 N 次”出現的模式 <a class="header-anchor" href="#_2-如何查找和替換每一行中-第-n-次-出現的模式" aria-label="Permalink to “2) 如何查找和替換每一行中“第 N 次”出現的模式”">​</a></h3><p>在行中使用<code>/1</code>、<code>/2</code>……<code>/n</code> 等標誌來代替相應的匹配。</p><p>下面的 <code>sed</code> 命令在一行中用 <code>linux</code> 來替換 <code>unix</code> 模式的第二個實例。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sed &#39;s/unix/linux/2&#39; sed-test.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1 Unix unix linux 23</span></span>
<span class="line"><span>2 linux Linux 34</span></span>
<span class="line"><span>3 linuxunix UnixLinux</span></span>
<span class="line"><span>linux /bin/bash CentOS Linux OS</span></span>
<span class="line"><span>Linux is free and opensource operating system</span></span></code></pre></div><h3 id="_3-如何搜索和替換一行中所有的模式實例" tabindex="-1">3) 如何搜索和替換一行中所有的模式實例 <a class="header-anchor" href="#_3-如何搜索和替換一行中所有的模式實例" aria-label="Permalink to “3) 如何搜索和替換一行中所有的模式實例”">​</a></h3><p>下面的 <code>sed</code> 命令用 <code>linux</code> 替換 <code>unix</code> 格式的所有實例，因為 <code>g</code> 是一個全局替換標誌。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sed &#39;s/unix/linux/g&#39; sed-test.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1 Unix linux linux 23</span></span>
<span class="line"><span>2 linux Linux 34</span></span>
<span class="line"><span>3 linuxlinux UnixLinux</span></span>
<span class="line"><span>linux /bin/bash CentOS Linux OS</span></span>
<span class="line"><span>Linux is free and opensource operating system</span></span></code></pre></div><h3 id="_4-如何查找和替換一行中從-第-n-個-開始的所有匹配的模式實例" tabindex="-1">4) 如何查找和替換一行中從“第 N 個”開始的所有匹配的模式實例 <a class="header-anchor" href="#_4-如何查找和替換一行中從-第-n-個-開始的所有匹配的模式實例" aria-label="Permalink to “4) 如何查找和替換一行中從“第 N 個”開始的所有匹配的模式實例”">​</a></h3><p>下面的 <code>sed</code> 命令在一行中替換從模式的“第 N 個”開始的匹配實例。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sed &#39;s/unix/linux/2g&#39; sed-test.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1 Unix unix linux 23</span></span>
<span class="line"><span>2 linux Linux 34</span></span>
<span class="line"><span>3 linuxunix UnixLinux</span></span>
<span class="line"><span>linux /bin/bash CentOS Linux OS</span></span>
<span class="line"><span>Linux is free and opensource operating system</span></span></code></pre></div><h3 id="_5-在特定的行號搜索和替換模式" tabindex="-1">5) 在特定的行號搜索和替換模式 <a class="header-anchor" href="#_5-在特定的行號搜索和替換模式" aria-label="Permalink to “5) 在特定的行號搜索和替換模式”">​</a></h3><p>你可以替換特定行號中的字符串。下面的 <code>sed</code> 命令用 <code>linux</code> 僅替換第三行的 <code>unix</code> 模式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sed &#39;3 s/unix/linux/&#39; sed-test.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1 Unix unix unix 23</span></span>
<span class="line"><span>2 linux Linux 34</span></span>
<span class="line"><span>3 linuxlinux UnixLinux</span></span>
<span class="line"><span>linux /bin/bash CentOS Linux OS</span></span>
<span class="line"><span>Linux is free and opensource operating system</span></span></code></pre></div><h3 id="_6-在特定範圍行號間搜索和替換模式" tabindex="-1">6) 在特定範圍行號間搜索和替換模式 <a class="header-anchor" href="#_6-在特定範圍行號間搜索和替換模式" aria-label="Permalink to “6) 在特定範圍行號間搜索和替換模式”">​</a></h3><p>你可以指定行號的範圍，以替換字符串。</p><p>下面的 <code>sed</code> 命令在 1 到 3 行間用 <code>linux</code> 替換 <code>Unix</code> 模式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sed &#39;1,3 s/unix/linux/&#39; sed-test.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1 Unix linux unix 23</span></span>
<span class="line"><span>2 linux Linux 34</span></span>
<span class="line"><span>3 linuxlinux UnixLinux</span></span>
<span class="line"><span>linux /bin/bash CentOS Linux OS</span></span>
<span class="line"><span>Linux is free and opensource operating system</span></span></code></pre></div><h3 id="_7-如何查找和修改最後一行的模式" tabindex="-1">7) 如何查找和修改最後一行的模式 <a class="header-anchor" href="#_7-如何查找和修改最後一行的模式" aria-label="Permalink to “7) 如何查找和修改最後一行的模式”">​</a></h3><p>下面的 sed 命令允許你只在最後一行替換匹配的字符串。</p><p>下面的 <code>sed</code> 命令只在最後一行用 <code>Unix</code> 替換 <code>Linux</code> 模式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sed &#39;$ s/Linux/Unix/&#39; sed-test.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1 Unix unix unix 23</span></span>
<span class="line"><span>2 linux Linux 34</span></span>
<span class="line"><span>3 linuxunix UnixLinux</span></span>
<span class="line"><span>linux /bin/bash CentOS Linux OS</span></span>
<span class="line"><span>Unix is free and opensource operating system</span></span></code></pre></div><h3 id="_8-在一行中如何只查找和替換正確的模式匹配" tabindex="-1">8) 在一行中如何只查找和替換正確的模式匹配 <a class="header-anchor" href="#_8-在一行中如何只查找和替換正確的模式匹配" aria-label="Permalink to “8) 在一行中如何只查找和替換正確的模式匹配”">​</a></h3><p>你可能已經注意到，子串 <code>linuxunix</code> 被替換為在第 6 個示例中的 <code>linuxlinux</code>。如果你只想更改正確的匹配詞，在搜索串的兩端用這個邊界符 <code>\\b</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sed &#39;1,3 s/\\bunix\\b/linux/&#39; sed-test.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1 Unix linux unix 23</span></span>
<span class="line"><span>2 linux Linux 34</span></span>
<span class="line"><span>3 linuxunix UnixLinux</span></span>
<span class="line"><span>linux /bin/bash CentOS Linux OS</span></span>
<span class="line"><span>Linux is free and opensource operating system</span></span></code></pre></div><h3 id="_9-如何以不區分大小寫來搜索與替換模式" tabindex="-1">9) 如何以不區分大小寫來搜索與替換模式 <a class="header-anchor" href="#_9-如何以不區分大小寫來搜索與替換模式" aria-label="Permalink to “9) 如何以不區分大小寫來搜索與替換模式”">​</a></h3><p>大家都知道，Linux 是區分大小寫的。為了與不區分大小寫的模式匹配，使用 <code>I</code> 標誌。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sed &#39;s/unix/linux/gI&#39; sed-test.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1 linux linux linux 23</span></span>
<span class="line"><span>2 linux Linux 34</span></span>
<span class="line"><span>3 linuxlinux linuxLinux</span></span>
<span class="line"><span>linux /bin/bash CentOS Linux OS</span></span>
<span class="line"><span>Linux is free and opensource operating system</span></span></code></pre></div><h3 id="_10-如何查找和替換包含分隔符的字符串" tabindex="-1">10) 如何查找和替換包含分隔符的字符串 <a class="header-anchor" href="#_10-如何查找和替換包含分隔符的字符串" aria-label="Permalink to “10) 如何查找和替換包含分隔符的字符串”">​</a></h3><p>當你搜索和替換含分隔符的字符串時，我們需要用反斜槓 <code>\\</code> 來取消轉義。</p><p>在這個例子中，我們將用 <code>/usr/bin/fish</code> 來替換 <code>/bin/bash</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sed &#39;s/\\/bin\\/bash/\\/usr\\/bin\\/fish/g&#39; sed-test.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1 Unix unix unix 23</span></span>
<span class="line"><span>2 linux Linux 34</span></span>
<span class="line"><span>3 linuxunix UnixLinux</span></span>
<span class="line"><span>linux /usr/bin/fish CentOS Linux OS</span></span>
<span class="line"><span>Linux is free and opensource operating system</span></span></code></pre></div><p>上述 <code>sed</code> 命令按預期工作，但它看起來來很糟糕。 為了簡化，大部分的人會用豎線 <code>|</code> 作為正則表達式的定位符。 所以，我建議你用它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sed &#39;s|/bin/bash|/usr/bin/fish/|g&#39; sed-test.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1 Unix unix unix 23</span></span>
<span class="line"><span>2 linux Linux 34</span></span>
<span class="line"><span>3 linuxunix UnixLinux</span></span>
<span class="line"><span>linux /usr/bin/fish/ CentOS Linux OS</span></span>
<span class="line"><span>Linux is free and opensource operating system</span></span></code></pre></div><h3 id="_11-如何以給定的模式來查找和替換數字" tabindex="-1">11) 如何以給定的模式來查找和替換數字 <a class="header-anchor" href="#_11-如何以給定的模式來查找和替換數字" aria-label="Permalink to “11) 如何以給定的模式來查找和替換數字”">​</a></h3><p>類似地，數字可以用模式來代替。下面的 <code>sed</code> 命令以 <code>[0-9]</code> 替換所有數字為 <code>number</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sed &#39;s/[0-9]/number/g&#39; sed-test.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>number Unix unix unix numbernumber</span></span>
<span class="line"><span>number linux Linux numbernumber</span></span>
<span class="line"><span>number linuxunix UnixLinux</span></span>
<span class="line"><span>linux /bin/bash CentOS Linux OS</span></span>
<span class="line"><span>Linux is free and opensource operating system</span></span></code></pre></div><h3 id="_12-如何用模式僅查找和替換兩個數字" tabindex="-1">12) 如何用模式僅查找和替換兩個數字 <a class="header-anchor" href="#_12-如何用模式僅查找和替換兩個數字" aria-label="Permalink to “12) 如何用模式僅查找和替換兩個數字”">​</a></h3><p>如果你想用模式來代替兩位數字，使用下面的 <code>sed</code> 命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sed &#39;s/\\b[0-9]\\{2\\}\\b/number/g&#39; sed-test.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1 Unix unix unix number</span></span>
<span class="line"><span>2 linux Linux number</span></span>
<span class="line"><span>3 linuxunix UnixLinux</span></span>
<span class="line"><span>linux /bin/bash CentOS Linux OS</span></span>
<span class="line"><span>Linux is free and opensource operating system</span></span></code></pre></div><h3 id="_13-如何用-sed-命令僅打印被替換的行" tabindex="-1">13) 如何用 sed 命令僅打印被替換的行 <a class="header-anchor" href="#_13-如何用-sed-命令僅打印被替換的行" aria-label="Permalink to “13) 如何用 sed 命令僅打印被替換的行”">​</a></h3><p>如果你想顯示僅更改的行，使用下面的 <code>sed</code> 命令。</p><ul><li><code>p</code> - 它在終端上輸出替換的行兩次。</li><li><code>-n</code> - 它抑制由 <code>p</code> 標誌所產生的重複行。</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sed -n &#39;s/Unix/Linux/p&#39; sed-test.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1 Linux unix unix 23</span></span>
<span class="line"><span>3 linuxunix LinuxLinux</span></span></code></pre></div><h3 id="_14-如何同時運行多個-sed-命令" tabindex="-1">14) 如何同時運行多個 sed 命令 <a class="header-anchor" href="#_14-如何同時運行多個-sed-命令" aria-label="Permalink to “14) 如何同時運行多個 sed 命令”">​</a></h3><p>以下 <code>sed</code> 命令同時檢測和置換兩個不同的模式。</p><p>下面的 <code>sed</code> 命令搜索 <code>linuxunix</code> 和 <code>CentOS</code> 模式，用 <code>LINUXUNIX</code> 和 <code>RHEL8</code> 一次性更換它們。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sed -e &#39;s/linuxunix/LINUXUNIX/g&#39; -e &#39;s/CentOS/RHEL8/g&#39; sed-test.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1 Unix unix unix 23</span></span>
<span class="line"><span>2 linux Linux 34</span></span>
<span class="line"><span>3 LINUXUNIX UnixLinux</span></span>
<span class="line"><span>linux /bin/bash RHEL8 Linux OS</span></span>
<span class="line"><span>Linux is free and opensource operating system</span></span></code></pre></div><p>下面的 <code>sed</code> 命令搜索替換兩個不同的模式，並一次性替換為一個字符串。</p><p>以下 <code>sed</code> 的命令搜索 <code>linuxunix</code> 和 <code>CentOS</code> 模式，用 <code>Fedora30</code> 替換它們。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sed -e &#39;s/\\(linuxunix\\|CentOS\\)/Fedora30/g&#39; sed-test.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1 Unix unix unix 23</span></span>
<span class="line"><span>2 linux Linux 34</span></span>
<span class="line"><span>3 Fedora30 UnixLinux</span></span>
<span class="line"><span>linux /bin/bash Fedora30 Linux OS</span></span>
<span class="line"><span>Linux is free and opensource operating system</span></span></code></pre></div><h3 id="_15-如果給定的模式匹配-如何查找和替換整個行" tabindex="-1">15) 如果給定的模式匹配，如何查找和替換整個行 <a class="header-anchor" href="#_15-如果給定的模式匹配-如何查找和替換整個行" aria-label="Permalink to “15) 如果給定的模式匹配，如何查找和替換整個行”">​</a></h3><p>如果模式匹配，可以使用 <code>sed</code> 命令用新行來代替整行。這可以通過使用 <code>c</code> 標誌來完成。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sed &#39;/OS/ c\\</span></span>
<span class="line"><span>New Line</span></span>
<span class="line"><span>&#39; sed-test.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1 Unix unix unix 23</span></span>
<span class="line"><span>2 linux Linux 34</span></span>
<span class="line"><span>3 linuxunix UnixLinux</span></span>
<span class="line"><span>New Line</span></span>
<span class="line"><span>Linux is free and opensource operating system</span></span></code></pre></div><h3 id="_16-如何搜索和替換相匹配的模式行" tabindex="-1">16) 如何搜索和替換相匹配的模式行 <a class="header-anchor" href="#_16-如何搜索和替換相匹配的模式行" aria-label="Permalink to “16) 如何搜索和替換相匹配的模式行”">​</a></h3><p>在 <code>sed</code> 命令中你可以為行指定適合的模式。在匹配該模式的情況下，<code>sed</code> 命令搜索要被替換的字符串。</p><p>下面的 <code>sed</code> 命令首先查找具有 <code>OS</code> 模式的行，然後用 <code>ArchLinux</code> 替換單詞 <code>Linux</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sed &#39;/OS/ s/Linux/ArchLinux/&#39; sed-test.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1 Unix unix unix 23</span></span>
<span class="line"><span>2 linux Linux 34</span></span>
<span class="line"><span>3 linuxunix UnixLinux</span></span>
<span class="line"><span>linux /bin/bash CentOS ArchLinux OS</span></span>
<span class="line"><span>Linux is free and opensource operating system</span></span></code></pre></div><hr>`,81)),p("p",null,[s[1]||(s[1]=n("via: ",-1)),e(a,{href:"https://www.2daygeek.com/linux-sed-to-find-and-replace-string-in-files/"},{default:i(()=>[...s[0]||(s[0]=[n("https://www.2daygeek.com/linux-sed-to-find-and-replace-string-in-files/",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=n("作者：",-1)),e(a,{href:"https://www.2daygeek.com/author/magesh/"},{default:i(()=>[...s[2]||(s[2]=[n("Magesh Maruthamuthu",-1)])]),_:1}),s[7]||(s[7]=n(" 選題：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[n("lujun9972",-1)])]),_:1}),s[8]||(s[8]=n(" 譯者：",-1)),e(a,{href:"https://github.com/asche910"},{default:i(()=>[...s[4]||(s[4]=[n("Asche910",-1)])]),_:1}),s[9]||(s[9]=n(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[n("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[n("LCTT",-1)])]),_:1}),s[13]||(s[13]=n(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[n("Linux中國",-1)])]),_:1}),s[14]||(s[14]=n(" 榮譽推出",-1))])])}const y=l(u,[["render",h]]);export{L as __pageData,y as default};
